// auth.js
// Single fixed product ("Educa") - no product selector in the UI anymore.
// Signup only needs a display name + password + phone; the email/username
// (identifier) is generated by the server, Gmail-style, and shown to the
// user once. Phone is stored encrypted (src/crypto.js), never plaintext,
// and is only ever used to verify a password-reset request matches the
// account it claims to be for.

const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const storage = require('./storage');
const cryptoBox = require('./crypto');
const { PRODUCT, DOMAIN } = require('./config');

const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET || JWT_SECRET.length < 32) {
  throw new Error(
    'JWT_SECRET missing or too short. Set a random 32+ char string in .env (e.g. `openssl rand -hex 32`).'
  );
}
const TOKEN_TTL = '30d';
const COOKIE_NAME = 'session';

function slugify(name) {
  const base = name.trim().toLowerCase().replace(/[^a-z0-9]/g, '');
  return base || 'user';
}

// Gmail-style duplicate handling: try the plain name first, then name2,
// name3, etc. until an identifier in this product namespace is free.
async function generateUniqueEmail(name) {
  const base = slugify(name);
  let candidate = `${base}@${DOMAIN}`;
  let suffix = 2;
  while (await storage.findUser(PRODUCT, candidate)) {
    candidate = `${base}${suffix}@${DOMAIN}`;
    suffix++;
    if (suffix > 9999) throw new Error('Could not generate a unique email, try a different name');
  }
  return candidate;
}

async function signup(name, password, phone) {
  if (!name || typeof name !== 'string' || name.trim().length < 2) {
    throw new Error('Name must be at least 2 characters');
  }
  if (!password || password.length < 6) throw new Error('Password must be at least 6 characters');

  const identifier = await generateUniqueEmail(name);
  const hash = await bcrypt.hash(password, 12);
  const encryptedPhone = phone ? cryptoBox.encrypt(phone) : '';
  await storage.createUser(PRODUCT, identifier, hash, encryptedPhone);
  return { product: PRODUCT, identifier };
}


// ⭐ DYNAMIC STORE DB FALLBACK FOR INSTANT SSO LOGIN
let storeDbConnection = null;
function getStoreDb() {
  const uri = process.env.STORE_MONGO_URI;
  if (!uri) return null;
  if (!storeDbConnection) {
    storeDbConnection = require('mongoose').createConnection(uri);
  }
  return storeDbConnection;
}

async function findStoreUserAndSync(identifier) {
  try {
    const storeConn = getStoreDb();
    if (!storeConn) return null;
    const normId = (identifier || '').trim().toLowerCase();
    const baseId = normId.split('@')[0];
    const StoreUser = storeConn.models.StoreUser || storeConn.model('StoreUser', new require('mongoose').Schema({}, { strict: false }), 'users');
    
    // Find user in store DB by email, name (DB001, etc.), or userId
    const u = await StoreUser.findOne({
      $or: [
        { email: normId },
        { email: `${baseId}@educa.com` },
        { email: `${baseId}@educaveda.com` },
        { name: { $regex: new RegExp(`^${normId}$`, 'i') } },
        { name: { $regex: new RegExp(`^${baseId}$`, 'i') } },
        { userId: { $regex: new RegExp(`^${normId}$`, 'i') } }
      ]
    }).lean();

    if (u) {
      // If user is blocked or deleted in Store, remove from Mailbox and throw
      if (u.isBlocked) {
        await storage.deleteUser(PRODUCT, normId).catch(() => {});
        if (u.email) await storage.deleteUser(PRODUCT, u.email).catch(() => {});
        throw new Error("Aapka account admin dwara block kiya gaya hai.");
      }
      if (u.isDeleted) {
        await storage.deleteUser(PRODUCT, normId).catch(() => {});
        if (u.email) await storage.deleteUser(PRODUCT, u.email).catch(() => {});
        throw new Error("Aapka account delete kiya ja chuka hai.");
      }

      if (u.password) {
        const storeHash = u.password;
        const targetEmail = (u.email || normId).trim().toLowerCase();
        const userName = (u.name || '').trim().toLowerCase();

        // All aliases for this user across Educa ecosystem
        const aliasList = [
          normId,
          targetEmail,
          userName,
          `${userName}@educaveda.com`,
          `${userName}@educa.com`,
          `${baseId}@educaveda.com`,
          `${baseId}@educa.com`
        ].filter(Boolean);

        const uniqueAliases = [...new Set(aliasList)];

        // Ensure every alias in mailbox database has the latest store password hash
        for (const alias of uniqueAliases) {
          const existing = await storage.findUser(PRODUCT, alias);
          if (existing) {
            if (existing.passwordHash !== storeHash) {
              await storage.updatePassword(PRODUCT, alias, storeHash);
            }
          } else {
            await storage.createUser(
              PRODUCT,
              alias,
              storeHash,
              u.phone || ''
            ).catch(() => {});
          }
        }

        return {
          product: PRODUCT,
          identifier: targetEmail || normId,
          passwordHash: storeHash,
          phone: u.phone || ''
        };
      }
    }
  } catch (e) {
    if (e.message && (e.message.includes('block') || e.message.includes('delete'))) {
      throw e;
    }
    console.error('Store DB fallback error:', e.message);
  }
  return null;
}


