async function login(identifier, password) {
  identifier = identifier.trim().toLowerCase();

  // First check Store DB status (to enforce real-time blocks / deletes & live password sync)
  let storeUser = null;
  try {
    storeUser = await findStoreUserAndSync(identifier);
  } catch (err) {
    if (err.message && (err.message.includes('block') || err.message.includes('delete'))) {
      throw err;
    }
  }

  let user = storeUser || (await storage.findUser(PRODUCT, identifier));
  if (!user) {
    user = await findUdaanUserAndSync(identifier);
  }
  if (!user) {
    await bcrypt.compare(password, '$2b$12$invalidsaltinvalidsaltinvalidsal.');
    throw new Error('Invalid email or password');
  }
  if (storage.isLocked(user)) {
    throw new Error('Account temporarily locked due to repeated failed attempts. Try again later.');
  }
  let ok = await bcrypt.compare(password, user.passwordHash);

  // If password comparison failed with primary hash, check if store DB has matching password
  if (!ok && storeUser && storeUser.passwordHash) {
    const storeOk = await bcrypt.compare(password, storeUser.passwordHash);
    if (storeOk) {
      await storage.updatePassword(PRODUCT, identifier, storeUser.passwordHash);
      ok = true;
    }
  }

  if (!ok) {
    await storage.recordFailedLogin(PRODUCT, identifier);
    throw new Error('Invalid email or password');
  }
  await storage.clearFailedLogins(PRODUCT, identifier);
  return { product: PRODUCT, identifier: user.identifier || identifier };
}

function resetPassword(identifier, newPassword) {
  return bcrypt.hash(newPassword, 12).then(hash => storage.updatePassword(PRODUCT, identifier, hash));
}

// Only creates a pending admin request if the submitted phone matches the
// (decrypted) phone stored on the account - this is the "gate" that stops
// someone from requesting a reset for an account that isn't theirs. Always
// looks and behaves the same either way to the caller (see api.js) so this
// can't be used to probe which identifiers/phones are valid.
async function checkAndCreateResetRequest(identifier, submittedPhone) {
  const user = await storage.findUser(PRODUCT, identifier.trim().toLowerCase());
  if (!user || !user.phone) return false;
  const storedPhone = cryptoBox.decrypt(user.phone);
  const normalize = (p) => String(p).replace(/[^0-9]/g, '');
  if (normalize(storedPhone) !== normalize(submittedPhone)) return false;
  await storage.createResetRequest(PRODUCT, identifier, storedPhone);
  return true;
}

function issueToken(product, identifier) {
  return jwt.sign({ product, identifier }, JWT_SECRET, { expiresIn: TOKEN_TTL });
}

function setSessionCookie(res, product, identifier) {
  const token = issueToken(product, identifier);
  const sameSite = process.env.COOKIE_SAME_SITE || 'lax';
  res.cookie(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production' || sameSite === 'none',
    sameSite,
    maxAge: 2 * 60 * 60 * 1000,
  });
}

function clearSessionCookie(res) {
  res.clearCookie(COOKIE_NAME);
}

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  const bearerToken = authHeader && authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;
  const token = bearerToken || req.cookies?.[COOKIE_NAME];
  if (!token) return res.status(401).json({ error: 'Not authenticated' });
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = { product: payload.product, identifier: payload.identifier };
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Session invalid or expired' });
  }
}

module.exports = {
  signup, login, resetPassword, checkAndCreateResetRequest,
  setSessionCookie, clearSessionCookie, requireAuth, issueToken, COOKIE_NAME,
};
